WITH unpacked AS (SELECT id, effective_from, currency, discounts, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ELEMENT_AT(tier_prices, 1) AS entry_price, ARRAY_MIN(tier_prices) AS lowest_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers) SELECT id, effective_from, currency, discounts, avg_tier_price, entry_price, lowest_price, tier_revenue_caps, first_two_limits, FIRST_VALUE(lowest_price, TRUE) OVER (PARTITION BY currency ORDER BY avg_tier_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_lowest_price, LEAD(entry_price, 2, 0) OVER (PARTITION BY currency ORDER BY entry_price, id) AS next_entry_price FROM unpacked;
